#include <iostream>
#include <cstdint>
#include <cstring>
#include <chrono>
#include <thread>
#include <vector>
#include <algorithm>

struct RateLimitConfig {
    uint32_t max_retries;
    uint32_t base_delay_ms;
    uint32_t max_delay_ms;
    uint32_t backoff_factor;
};

struct RequestContext {
    uint32_t attempt_count;
    uint32_t current_delay_ms;
    uint32_t total_wait_ms;
    bool success;
};

// Compute exponential backoff delay with jitter
uint32_t compute_backoff_delay(const RateLimitConfig& config, uint32_t attempt) {
    // Calculate base exponential: base_delay * (backoff_factor ^ attempt)
    uint32_t delay = config.base_delay_ms;
    for (uint32_t i = 0; i < attempt; i++) {
        uint32_t next = delay * config.backoff_factor;
        // Overflow protection: cap at max_delay
        if (next / config.backoff_factor != delay) {
            return config.max_delay_ms;
        }
        delay = next;
    }
    // Cap at maximum
    return std::min(delay, config.max_delay_ms);
}

// Allocate a response buffer sized proportionally to accumulated wait time
// The idea: longer waits suggest larger responses from server batch processing
char* allocate_response_buffer(const RequestContext& ctx) {
    // Scale factor: 16 bytes per ms of total wait, plus base 256 bytes
    // This heuristic accounts for server-side batching during our backoff
    uint32_t scale_factor = 16;
    uint32_t base_size = 256;
    uint32_t buffer_size = base_size + (ctx.total_wait_ms * scale_factor);

    // Safety check: don't allocate more than 64MB
    if (buffer_size > 64 * 1024 * 1024) {
        buffer_size = 64 * 1024 * 1024;
    }

    char* buf = new(std::nothrow) char[buffer_size];
    if (buf) {
        memset(buf, 0, buffer_size);
    }
    return buf;
}

// Simulate sending a request that may fail
bool send_request(const char* endpoint, int attempt_num) {
    // Simulate: first few attempts fail with rate limit
    return attempt_num >= 3;
}

int perform_request_with_retry(const char* endpoint, const RateLimitConfig& config) {
    RequestContext ctx = {0, 0, 0, false};

    for (uint32_t attempt = 0; attempt <= config.max_retries; attempt++) {
        ctx.attempt_count = attempt;

        if (send_request(endpoint, attempt)) {
            ctx.success = true;

            // Allocate buffer for response based on accumulated context
            char* response = allocate_response_buffer(ctx);
            if (!response) {
                std::cerr << "Failed to allocate response buffer" << std::endl;
                return -1;
            }

            // Process response...
            std::cout << "Request succeeded on attempt " << attempt + 1 << std::endl;
            delete[] response;
            return 0;
        }

        if (attempt < config.max_retries) {
            uint32_t delay = compute_backoff_delay(config, attempt);
            ctx.current_delay_ms = delay;
            ctx.total_wait_ms += delay;

            std::cout << "Attempt " << attempt + 1 << " failed. "
                      << "Waiting " << delay << "ms before retry..." << std::endl;
            std::this_thread::sleep_for(std::chrono::milliseconds(delay));
        }
    }

    std::cerr << "All retry attempts exhausted." << std::endl;
    return -1;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <endpoint> [max_retries] [base_delay_ms] [backoff_factor]" << std::endl;
        return 1;
    }

    RateLimitConfig config;
    config.max_retries = 5;
    config.base_delay_ms = 1000;
    config.max_delay_ms = 60000;
    config.backoff_factor = 2;

    if (argc >= 3) config.max_retries = static_cast<uint32_t>(std::stoul(argv[2]));
    if (argc >= 4) config.base_delay_ms = static_cast<uint32_t>(std::stoul(argv[3]));
    if (argc >= 5) config.backoff_factor = static_cast<uint32_t>(std::stoul(argv[4]));

    // Validate configuration
    if (config.max_retries > 20) {
        std::cerr << "max_retries capped at 20" << std::endl;
        config.max_retries = 20;
    }
    if (config.backoff_factor < 1 || config.backoff_factor > 10) {
        std::cerr << "backoff_factor must be 1-10" << std::endl;
        return 1;
    }
    if (config.base_delay_ms > 30000) {
        std::cerr << "base_delay_ms capped at 30000" << std::endl;
        config.base_delay_ms = 30000;
    }

    return perform_request_with_retry(argv[1], config);
}
